def transform(grid):
    h, w = len(grid), len(grid[0])
    rows_by_color = {}
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0:
                rows_by_color.setdefault(grid[r][c], []).append(r)

    if not rows_by_color:
        return [row[:] for row in grid]

    top = min(min(rows) for rows in rows_by_color.values())
    out = [[0] * w for _ in range(h)]
    for color, rows in rows_by_color.items():
        shift = top - min(rows)
        for r in range(h):
            for c in range(w):
                if grid[r][c] == color:
                    nr = r + shift
                    if 0 <= nr < h:
                        out[nr][c] = color
    return out
